'use strict';
// V1 availability layer. Future features stay discoverable but do not expose
// their unfinished editors or guided experiences to an end user.
const V1_UPCOMING={
 tutorial:{title:'Tutoriels guidés',subtitle:'Les gestes, étape par étape.',image:'bun-small',features:['Coiffure et maquillage en étapes visuelles','Reprise automatique au bon moment','Alternatives selon le matériel disponible']},
 makeup:{title:'Maquillage',subtitle:'Des recettes reliées à vos couleurs.',image:'eye',features:['Recommandations par occasion et durée','Teintes issues de votre profil couleur','Recettes naturelles, soft glam et soirée']},
 wardrobe:{title:'Garde-robe',subtitle:'Composer avec les pièces que vous possédez.',image:'wardrobe',features:['Vêtements détourés et organisés','Tenues composées avec votre palette','Préparation pour une date ou une occasion']}
};
const V1_BASE={card,openItem,recommendations,weekCandidates,eventForm:F.event,eventSelect:ACTIONS['event-select'],eventTutorial:ACTIONS['event-tutorial'],product:V['DEC-06']};

function v1UpcomingKey(x){if(!x)return '';if(x.type==='Tutoriel')return 'tutorial';if(x.domain==='Maquillage')return 'makeup';if(x.domain==='Garde-robe')return 'wardrobe';return '';}
function v1UpcomingPage(key){const f=V1_UPCOMING[key],saved=!!M.comingSoonNotices?.[key];return head(f.title,'Une fonctionnalité Beautify à venir.')+`<section class="coming-hero">${imageFor(f.image,'coming-image',f.title)}<div class="coming-shade"></div><span class="coming-pill">Bientôt</span><div class="coming-copy"><h2>${esc(f.subtitle)}</h2><p>Cette expérience reste visible pour présenter la suite du produit.</p></div></section>`+sec('Ce qui est prévu')+`<div class="coming-list">${f.features.map((x,i)=>`<div><span>${i+1}</span><p>${esc(x)}</p></div>`).join('')}</div>`+A(saved?'Vous serez prévenue':'Me prévenir au lancement','coming-notify',{feature:key,pressed:saved},saved?'secondary':'primary')+B('Retour aux fonctions disponibles',key==='tutorial'?'DEC-01':key==='makeup'?'COL-01':'DEC-01','text-button mt')+note('Aucune date de sortie ni notification réelle dans ce mockup.');}
function v1ComingCard(key){const f=V1_UPCOMING[key];return A(`${imageFor(f.image,'',f.title)}<span class="card-type">Bientôt</span><h3>${esc(f.title)}</h3><p>${esc(f.subtitle)}</p>`,'coming-open',{feature:key},'content-card coming-card');}

card=function(x){const key=v1UpcomingKey(x);return key?v1ComingCard(key):V1_BASE.card(x);};
openItem=function(id){const x=item(id),key=v1UpcomingKey(x);if(key){go(key==='tutorial'?'DEC-04':key==='makeup'?'MAQ-01':'GAR-01');return;}V1_BASE.openItem(id);};
recommendations=function(domain){if(['Maquillage','Garde-robe'].includes(domain))return [];return V1_BASE.recommendations(domain).filter(x=>!v1UpcomingKey(x));};
weekCandidates=function(){return V1_BASE.weekCandidates().filter(x=>!v1UpcomingKey(x));};

V['ENT-03']=()=>head('Une envie pour commencer ?','Votre premier raccourci, vous pourrez explorer le reste ensuite.')+intent('Trouver une idée rapide','Cheveux, couleurs ou routine de peau','start-intent',{intent:'look'},'sparkles')+intent('Préparer une occasion','Choisir ma coiffure pour une date','start-intent',{intent:'event'},'calendar')+intent('Créer un rituel à moi','Mes gestes de soin, à mon rythme','start-intent',{intent:'routine'},'sun')+`<div class="coming-inline"><span>Bientôt</span><p>Maquillage, garde-robe et tutoriels guidés rejoindront ces parcours.</p></div>`+B('Je préfère explorer librement','DEC-01','text-button mt');
V['ENT-04']=()=>head('Une inspiration à ma mesure','Deux repères suffisent pour commencer.')+form('onboarding',select('time','Combien de temps aujourd’hui ?',['Moins de 5 min','10–15 min','20–30 min','Sans préférence'],M.prefs.time)+moreActions(chips(['Cheveux','Colorimétrie','Peau'],'interests',M.prefs.interests)+`<div class="coming-inline"><span>Bientôt</span><p>Vos préférences maquillage et garde-robe seront ajoutées avec ces fonctionnalités.</p></div>`,'Mes univers'),'Trouver mes premières idées');
V['ACC-01']=()=>{const actions=dailyActions(),next=M.events.filter(e=>e.date>=DATE()&&e.status!=='done').sort((a,b)=>a.date.localeCompare(b.date))[0];return head(M.profile.name?'Bonjour '+esc(M.profile.name):'Un moment pour vous',dateText(DATE()))+studioStrip()+sec('Pour aujourd’hui','ACC-03','Ma journée')+(actions.length?actions.slice(0,2).map(taskRow).join(''):intent('Une idée en quelques minutes','Cheveux, couleurs ou soin de la peau','catalog',{time:'5 minutes'},'sparkles'))+`<div class="quick-links">${B(icon('calendar')+' Ma semaine','ACC-02','secondary')}${B(icon('sun')+' Mes routines','ROU-01','secondary')}</div>`+(next?sec('Ma prochaine occasion','EVE-01')+eventCard(next):intent('Préparer une occasion','Choisir une coiffure pour une date','new-event',{},'calendar'))+sec('Une inspiration pour moi','DEC-01')+grid(recommendations().slice(0,2))+moreActions(B('Mon journal et mes habitudes','PRO-01','secondary')+B('Toutes mes occasions','EVE-01','secondary mt')+B('Mes messages','ACC-04','secondary mt'),'Retrouver mon espace');};
V['DEC-01']=()=>head('Découvrir','Les expériences disponibles et celles qui arrivent ensuite.')+A(icon('search')+' Rechercher une inspiration…','catalog',{},'search-entry')+sec('Disponible maintenant')+`<div class="universe-list">${[['Cheveux','hair','HAI-01'],['Couleurs','palette','COL-01'],['Peau','leaf','PEA-01']].map(([t,i,p])=>B(icon(i)+`<span>${t}</span>`,p,'universe')).join('')}</div>`+sec('Bientôt dans Beautify')+`<div class="coming-preview-grid">${['makeup','wardrobe','tutorial'].map(v1ComingCard).join('')}</div>`+sec('Selon vos envies','PRF-03','Affiner')+grid(recommendations())+note('Les fonctions marquées « Bientôt » sont des aperçus et ne sont pas incluses dans la V1.');
V['DEC-04']=()=>v1UpcomingPage('tutorial');
V['MAQ-01']=()=>v1UpcomingPage('makeup');
['GAR-01','GAR-02','GAR-03','GAR-04'].forEach(id=>V[id]=()=>v1UpcomingPage('wardrobe'));
V['DEC-06']=()=>item(M.context.product)?.domain==='Maquillage'?v1UpcomingPage('makeup'):V1_BASE.product();

V['ANA-02']=()=>head('Que souhaitez-vous analyser ?','Les trois analyses disponibles dans la V1.')+progress(1,5)+`<div class="studio-stack compact">${studioCard('Trouver une coupe','Recommandations et essai sur votre photo.','studio-analysis','Cheveux','hair')}${studioCard('Trouver mes couleurs','Une palette personnelle et réutilisable.','studio-analysis','Colorimétrie','palette')}${studioCard('Construire ma routine','Les besoins observés et vos ressentis.','studio-analysis','Peau','leaf')}</div>`+`<div class="coming-inline"><span>Bientôt</span><p>Le maquillage et la garde-robe utiliseront ensuite vos résultats couleur.</p></div>`+B('Découvrir sans analyse','DEC-01','text-button mt');

V['EVE-02']=()=>{const e=M.eventEdit||{name:'',date:DATE(),occasion:'Événement',needs:['Cheveux']};return head(e.id?'Modifier mon occasion':'Une occasion à préparer')+form('event',field('name','Nom de l’occasion',e.name,'text',true)+field('date','Date',e.date,'date',true)+select('occasion','Type d’occasion',['Quotidien','Travail','Rendez-vous','Événement'],e.occasion)+moreActions(field('time','Horaire',e.time,'time')+field('place','Lieu',e.place)+field('dresscode','Indication utile',e.dresscode)+area('notes','Notes',e.notes||'')+`<fieldset><legend>Disponible dans la V1</legend>${check('needCheveux','Cheveux',(e.needs||[]).includes('Cheveux'))}</fieldset><div class="coming-inline"><span>Bientôt</span><p>Maquillage et garde-robe pourront compléter cette occasion.</p></div>`,'Ajouter des détails — facultatif'),'Garder mon occasion');};
V['EVE-03']=()=>{const e=currentEvent();if(!e)return empty('Cette occasion n’est plus disponible','Retrouvez vos autres événements.','EVE-01','Mes occasions');const domains=['Cheveux'],n=domains.filter(d=>e.look[d]).length;return head(esc(e.name),dateText(e.date)+(e.time?', '+esc(e.time):''))+tag(e.status==='done'?'Terminée':n?'Coiffure choisie':'À préparer')+(e.dresscode?P(esc(e.dresscode)):'')+sec('Disponible dans la V1')+domains.map(d=>row(d,e.look[d]?esc(item(e.look[d])?.name||'À remplacer'):'À choisir','EVE-04','hair')).join('')+`<div class="coming-inline"><span>Bientôt</span><p>Le maquillage et la tenue rejoindront cette préparation dans une prochaine version.</p>${A('Voir le maquillage','coming-open',{feature:'makeup'},'text-button')}${A('Voir la garde-robe','coming-open',{feature:'wardrobe'},'text-button')}</div>`+B(n?'Ma checklist':'Choisir ma coiffure',n?'EVE-05':'EVE-04')+moreActions(A('Modifier l’occasion','edit-event',{},'secondary')+A(e.status==='done'?'Remettre à venir':'Marquer l’occasion terminée','event-done',{},'text-button mt')+A('Supprimer cette occasion','delete-event-request',{},'text-button mt'))+(e.place||e.notes?sec('Les détails')+P(esc(e.place||''))+P(esc(e.notes||'')):'');};
V['EVE-04']=()=>{const e=currentEvent();if(!e)return empty('Choisissez une occasion','Votre préparation sera liée à cet événement.','EVE-01','Mes occasions');const domains=[...new Set(['Cheveux',...(e.needs||[]).filter(x=>!['Maquillage','Garde-robe'].includes(x))])];return head('Ma préparation pour '+esc(e.name),dateText(e.date))+domains.map(d=>{const x=item(e.look[d]);return `<section class="glass component-row">${x?imageFor(x.image,'component-photo',x.name):`<span class="component-placeholder">${icon('hair')}</span>`}<div><h2>${d}</h2><p>${x?esc(x.name):'À choisir'}</p>${A(x?'Remplacer':'Choisir','event-select',{domain:d},'text-button')}</div>${x?A(icon('x'),'event-remove-component',{domain:d,label:'Retirer le choix '+d},'icon-button'):''}</section>`;}).join('')+`<div class="coming-inline"><span>Bientôt</span><p>Ajouter le maquillage et la tenue à cette occasion.</p>${A('Voir l’aperçu','coming-open',{feature:'wardrobe'},'text-button')}</div>`+B('Voir ma préparation','EVE-05')+B('Retour à mon occasion','EVE-03','text-button mt');};
V['EVE-05']=()=>{const e=currentEvent();if(!e)return empty('Aucune occasion sélectionnée','Retrouvez votre préparation.','EVE-01');const x=item(e.look.Cheveux);return head('Ma checklist',esc(e.name)+', '+dateText(e.date))+`<div class="glass check-task ${e.tasks.Cheveux?'done':''}">${x?A(`<span class="check-circle">${e.tasks.Cheveux?icon('check'):''}</span>`,'event-task',{domain:'Cheveux',pressed:!!e.tasks.Cheveux,label:'Valider ou corriger Cheveux'},'icon-button'):icon('plus')}<span class="label"><strong>Cheveux</strong><small>${x?esc(x.name):'Choisir une idée'}</small></span>${x?B('Voir','DEC-03','text-button',{key:'look',value:x.id}):A('Choisir','event-select',{domain:'Cheveux'},'text-button')}</div>`+`<div class="coming-inline"><span>Bientôt</span><p>Les checklists maquillage et tenue apparaîtront ici à leur lancement.</p></div>`+form('event-note',area('note','Une note pour cette occasion',e.prepNote||''),'Garder ma note')+B('Revoir ma coiffure','EVE-04','secondary mt');};

V['PRE-01']=()=>head('Beautify Premium','Ce qui est réellement inclus dans la V1.')+`<section class="glass premium-value"><span class="eyebrow">Inclus chaque mois</span><h2>10 simulations<br><span class="accent">de coupes</span></h2><p>Vos recommandations de coupes, votre profil couleur, votre analyse de peau et vos routines personnalisables.</p>${B('Voir Hair Studio','HAI-01','secondary')}</section>`+`<div class="offer-comparison"><div><span>Disponible maintenant</span><p>Hair Studio, Color Studio, Skin Studio, favoris, historique et routines de peau.</p></div><div><span>Bientôt</span><p>Tutoriels guidés, maquillage et garde-robe. Ces modules ne sont pas présentés comme inclus aujourd’hui.</p></div></div>`+`<fieldset class="billing"><legend>Mon rythme</legend>${['monthly','yearly'].map(v=>A(`<strong>${v==='yearly'?'Annuel':'Mensuel'}</strong><span>${v==='yearly'?'59,99 € / an':'9,99 € / mois'}</span><small>${v==='yearly'?'12 mois, hypothèse à tester':'Un mois, hypothèse à tester'}</small>`,'offer',{value:v,pressed:M.subscription.offer===v},M.subscription.offer===v?'selected':'')).join('')}</fieldset>`+A('Choisir Premium — démo','subscribe')+A('Continuer en découverte','premium-return',{},'text-button mt')+note('Offre et prix fictifs. Aucun paiement réel dans ce mockup.');
V['PRF-03']=()=>{const p=M.preferenceEdit||M.prefs;return head('Mes goûts et mes besoins','Vous gardez la main. Vos anciens comptes rendus ne changeront pas.')+sec('Disponible maintenant')+chips(['Cheveux','Colorimétrie','Peau','Habitudes'],'interests',p.interests)+form('preferences',select('hair','Texture de cheveux',['Raides','Ondulés','Bouclés','Crépus','Je ne sais pas'],p.hair)+select('time','Temps disponible',['Moins de 5 min','10–15 min','20–30 min','Sans préférence'],p.time)+select('style','Style apprécié',['Sans préférence','Naturel','Minimaliste','Élégant','Créatif'],p.style)+field('budget','Budget indicatif — facultatif',p.budget)+area('avoid','Ce que je préfère éviter — facultatif',p.avoid),'Garder mes préférences')+`<div class="coming-inline"><span>Bientôt</span><p>Les préférences maquillage et garde-robe seront configurables au lancement de ces modules.</p></div>`+(Object.keys(M.contentFeedback||{}).length?A('Réinitialiser mes retours sur les looks','reset-feedback',{},'text-button mt'):'')+A('Retirer mes préférences','clear-prefs-request',{},'text-button mt');};
V['PRF-06']=()=>head('Mon abonnement',subscriptionLabel())+panel(`<h2>${M.subscription.status==='active'?'Mon espace Premium':'Mon accès découverte'}</h2>${P(M.subscription.status==='active'?'Vos studios V1 et vos 10 simulations mensuelles de coupes.':'Explorez les studios disponibles et vos routines de peau.')}`)+(M.subscription.status==='active'?B('Retrouver ma semaine','ACC-02')+A('Gérer mon abonnement','manage-subscription',{},'secondary mt'):B('Ce que propose Premium','PRE-01'))+B('Retrouver un accès existant','PRE-04','text-button mt')+note('Maquillage, garde-robe et tutoriels sont annoncés « Bientôt » et restent verrouillés dans cette V1. Aucune souscription réelle.');

tutorialLabel=function(){return 'Tutoriels à venir';};
startTutorial=function(id){if(item(id))M.context.look=id;go('DEC-04');};
routineStarterList=function(){return ROUTINE_STARTERS.filter(r=>r.domain!=='Garde-robe').map(r=>A(`<span class="row-label">${icon('leaf','accent')}<span><strong>${esc(r.name)}</strong><small>${r.minutes} min, ${r.steps.length} gestes à personnaliser</small></span></span>${icon('chev')}`,'routine-starter',{id:r.id},'glass list-row')).join('')+A(`<span class="row-label">${icon('dress','accent')}<span><strong>Ma tenue prête pour demain</strong><small>À venir avec la garde-robe</small></span></span>${icon('chev')}`,'coming-open',{feature:'wardrobe'},'glass list-row');};

const v1StudioAnalysis=ACTIONS['studio-analysis'];
const v1RoutineStarter=ACTIONS['routine-starter'];
F.event=d=>V1_BASE.eventForm({...d,needMaquillage:false,'needGarde-robe':false});
Object.assign(ACTIONS,{
 'coming-open':d=>go(d.feature==='tutorial'?'DEC-04':d.feature==='makeup'?'MAQ-01':'GAR-01'),
 'coming-notify':d=>{M.comingSoonNotices||={};M.comingSoonNotices[d.feature]=true;persist();render();toast('Votre intérêt est gardé dans ce mockup.');},
 'studio-analysis':d=>{if(d.domain==='Maquillage'){go('MAQ-01');return;}if(d.domain==='Garde-robe'){go('GAR-01');return;}v1StudioAnalysis(d);},
 'event-select':d=>{if(d.domain==='Maquillage'){go('MAQ-01');return;}if(d.domain==='Garde-robe'){go('GAR-01');return;}V1_BASE.eventSelect(d);},
 'event-tutorial':()=>go('DEC-04'),
 tutorial:d=>startTutorial(d.id),
 'routine-starter':d=>{const r=ROUTINE_STARTERS.find(x=>x.id===d.id);if(r?.domain==='Garde-robe'){go('GAR-01');return;}v1RoutineStarter(d);},
 'new-event':d=>{M.eventEdit={name:'',date:d.date||DATE(),occasion:'Événement',needs:['Cheveux']};clearDrafts('event');go('EVE-02');},
 'go-makeup':()=>go('MAQ-01'),
});
